import { Injectable } from '@angular/core';
import { Solicitud } from '../models/solicitud.model';

@Injectable({
    providedIn: 'root'
})
export class PdfService {

    constructor() { }

    generateSolicitudPdf(solicitud: Solicitud) {
        import('pdfmake/build/pdfmake').then(pdfMake => {
            import('pdfmake/build/vfs_fonts').then(pdfFonts => {
                // @ts-ignore
                pdfMake.default.vfs = pdfFonts.default;

                const docDefinition: any = {
                    content: [
                        { text: 'Detalle de Solicitud', style: 'header' },
                        { text: `ID: ${solicitud.id}`, style: 'subheader' },
                        { text: `Fecha: ${new Date(solicitud.created_at).toLocaleDateString()}`, style: 'subheader' },

                        { text: 'Información del Solicitante', style: 'sectionHeader' },
                        {
                            table: {
                                widths: ['30%', '70%'],
                                body: [
                                    [{ text: 'Nombre:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.nombre_solicitante, style: 'limitantesTextStyle' }],
                                    [{ text: 'Puesto:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.puesto_solicitante, style: 'limitantesTextStyle' }],
                                    [{ text: 'Email:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.email_solicitante, style: 'limitantesTextStyle' }],
                                ]
                            },
                            layout: 'noBorders'
                        },
                        { text: '\n' },

                        { text: 'Información de la Empresa', style: 'sectionHeader' },
                        {
                            table: {
                                widths: ['30%', '70%'],
                                body: [
                                    [{ text: 'Nombre:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.nombre_empresa, style: 'limitantesTextStyle' }],
                                    [{ text: 'Municipio:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.municipio?.nombre || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Empleados:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.num_empleados, style: 'limitantesTextStyle' }],
                                    [{ text: 'Inicio Operaciones:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.ano_inicio_operaciones, style: 'limitantesTextStyle' }],
                                ]
                            },
                            layout: 'noBorders'
                        },
                        { text: '\n' },

                        { text: 'Actividad y Asociación', style: 'sectionHeader' },
                        {
                            table: {
                                widths: ['30%', '70%'],
                                body: [
                                    [{ text: 'Giro Principal:', bold: true, style: 'limitantesTextStyle'}, { text: solicitud.giro_principal?.nombre || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otro Giro:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otro_giro || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Miembro Asociación:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.es_miembro_asociacion, style: 'limitantesTextStyle' }],
                                    [{ text: 'Asociación:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.asociacion?.nombre || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otra Asociación:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otra_asociacion || 'N/A', style: 'limitantesTextStyle' }],
                                ]
                            },
                            layout: 'noBorders'
                        },
                        { text: '\n' },

                        { text: 'Limitantes', style: 'sectionHeader' },
                        {
                            table: {
                                widths: ['30%', '70%'],
                                body: [
                                    [{ text: 'Relacionado Gobierno:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.relacionado_gobierno, style: 'limitantesTextStyle' }],
                                    [{ text: 'Niveles Gobierno:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.niveles_gobierno?.map(n => n.nombre).join(', ') || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otro Nivel:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otro_nivel_gobierno || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Rel. Sitio Web:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.relacionado_sitio_web, style: 'limitantesTextStyle' }],
                                    [{ text: 'Limitantes Web:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.limitantes_sitio_web?.map(l => l.descripcion).join(', ') || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otra Lim. Web:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otra_limitante_sitio_web || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Rel. Leyes:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.relacionado_leyes, style: 'limitantesTextStyle' }],
                                    [{ text: 'Problemas Reg.:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.problemas_regulacion?.map(p => p.descripcion).join(', ') || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otro Prob. Reg.:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otro_problema_regulacion || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Rel. Trámites:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.relacionado_tramites, style: 'limitantesTextStyle' }],
                                    [{ text: 'Problemas Trámite:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.problemas_tramite?.map(p => p.descripcion).join(', ') || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Rel. Mercado:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.relacionado_mercado, style: 'limitantesTextStyle' }],
                                    [{ text: 'Limitantes Mercado:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.limitantes_mercado?.map(l => l.descripcion).join(', ') || 'N/A', style: 'limitantesTextStyle' }],
                                    [{ text: 'Otra Lim. Mercado:', bold: true, style: 'limitantesTextStyle' }, { text: solicitud.otra_limitante_mercado || 'N/A', style: 'limitantesTextStyle' }],
                                ]
                            },
                            layout: 'noBorders'
                        },
                        { text: '\n' },

                        { text: 'Descripción y Propuesta', style: 'sectionHeader' },
                        { text: 'Descripción de la Limitante:', bold: true, style: 'limitantesTextStyle', margin: [0, 5, 0, 2] },
                        { text: solicitud.descripcion_limitante || 'N/A', style: 'limitantesTextStyle', margin: [0, 0, 0, 10] },
                        { text: 'Propuesta de Solución:', bold: true, style: 'limitantesTextStyle', margin: [0, 5, 0, 2] },
                        { text: solicitud.propuesta_solucion || 'N/A', style: 'limitantesTextStyle', margin: [0, 0, 0, 10] },

                    ],
                    styles: {
                        defaultStyle: {
                            fontSize: 12,
                            color: '#000000'
                        },
                        header: {
                            fontSize: 12,
                            bold: true,
                            margin: [0, 0, 0, 10]
                        },
                        subheader: {
                            fontSize: 12,
                            bold: true,
                            margin: [0, 0, 0, 15]
                        },
                        sectionHeader: {
                            fontSize: 12,
                            bold: true,
                            color: '#000000',
                            margin: [0, 10, 0, 5],
                            decoration: 'underline'
                        },
                        limitantesTextStyle: {
                            fontSize: 10,
                            color: '#000000'
                        }
                    },
                };

                // @ts-ignore
                pdfMake.default.createPdf(docDefinition).download(`solicitud_${solicitud.id}.pdf`);
            });
        });
    }
}
