import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Solicitud } from '../../../models/solicitud.model';
import { SolicitudService } from '../../../controllers/solicitud.service';
import { Paginator } from '../../../controllers/super.service';
import { PaginadorComponent } from '../../../shared/paginador/paginador.component';
import { PdfService } from '../../../services/pdf.service';

@Component({
  selector: 'app-solicitudes-list',
  standalone: true,
  imports: [CommonModule, RouterModule, PaginadorComponent],
  templateUrl: './solicitudes-list.html'
})
export class SolicitudesListComponent implements OnInit {

  public solicitudes: Solicitud[] = [];
  public isLoading = true;
  public paginator: Paginator = { page: 1, per_page: 15 };
  public total_pages = 0;
  public total_items = 0;

  constructor(
    private solicitudService: SolicitudService,
    private pdfService: PdfService
  ) { }

  ngOnInit() {
    this.getData();
  }

  getData() {
    this.isLoading = true;
    this.solicitudService.get({ paginator: this.paginator }).then(response => {
      this.solicitudes = response.data ?? [];
      this.total_pages = response.total_pages ?? 0;
      this.total_items = response.total_items ?? 0;
      this.isLoading = false;
    });
  }

  onPerPageChange(per_page: number) {
    this.paginator.per_page = per_page;
    this.paginator.page = 1;
    this.getData();
  }

  downloadPdf(solicitud: Solicitud) {
    this.pdfService.generateSolicitudPdf(solicitud);
  }
}
